'        else if (event.key === "ArrowRight") { liveScroller.scrollLeft += 80; }',
'        else if (event.key === "PageUp") { liveScroller.scrollLeft -= step; }',
'        else if (event.key === "PageDown") { liveScroller.scrollLeft += step; }',
'        else if (event.key === "Home") { liveScroller.scrollLeft = 0; }',
