'      var available = Math.max(0, trackWidth - thumbWidth);',
'      thumb.style.width = thumbWidth + "px";',
'      thumb.style.transform = "translateX(" + (maximum > 0 ? Math.round(available * scroller.scrollLeft / maximum) : 0) + "px)";',
'      bar.classList.toggle("is-visible", maximum > 1);',
