    'begin',
    '    select',
    '    	count(a.TNo) into tmp',
    '    from PartyTDSMaster a',
    '    where a.PartyCode = :P140_PartyCode',
    '    	and a.TDSMasterCode = nvl(:P140_TDSMasterCode, ''$null$'')',
    '    ;',
    '    ----',
    '    if nvl(tmp, 0) <= 0 or nvl(getMyParameterValue(''AUTOTDSMASTER''), ''YES'') = ''YES''  then		',
