 p_id=>wwv_flow_imp.id(600743470889249244)
,p_process_sequence=>40
,p_process_point=>'AFTER_SUBMIT'
,p_region_id=>wwv_flow_imp.id(596723855758907765)
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Detail - Save Interactive Grid Data'
,p_static_id=>'detail-save-interactive-grid-data'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'Begin',
'    case :APEX$ROW_STATUS',
'        when ''C'' then',
'            Insert Into purchasebilldetail (                 ',
'										TNO,',
'					SNO,',
'					SERIALNO,',
'					PURCHASEORDERTNO,',
'					ITEMCODE,',
'					ITEMSPECIFICATIONCODE,',
'					DESCRIPTION,',
'					QUANTITY1,',
'					QUANTITY2,',
'					RATEMEASURINGUNITCODE,',
'					RATE,',
'					AMOUNT,',
'					FOOTERAMOUNT,',
'					TOTALAMOUNT,',
'					DOCUMENTSTATUSCODE,',
'					REMARK,',
'					OURRG23DNO,',
'					PARTYRG23DNO,',
'					ROUNDING,',
'					FOOTERAMOUNTWITHRATE,',
'					JOBORDERTNO,',
'					TAXRULECODE,',
'					PRORATA,',
'					QUALITYCODE',
'',
'            )',
'            Values (',
'									:TNO,',
'					:SNO,',
'					:SERIALNO,',
'					:PURCHASEORDERTNO,',
'					:ITEMCODE,',
'					:ITEMSPECIFICATIONCODE,',
'					:DESCRIPTION,',
'					:QUANTITY1,',
'					:QUANTITY2,',
'					:RATEMEASURINGUNITCODE,',
'					:RATE,',
'					:AMOUNT,',
'					:FOOTERAMOUNT,',
'					:TOTALAMOUNT,',
'					:DOCUMENTSTATUSCODE,',
'					:REMARK,',
'					:OURRG23DNO,',
'					:PARTYRG23DNO,',
'					:ROUNDING,',
'					:FOOTERAMOUNTWITHRATE,',
'					:JOBORDERTNO,',
'					:TAXRULECODE,',
'					:PRORATA,',
'					:QUALITYCODE',
'',
'            );',
'        ',
'        when ''U'' then',
'            update purchasebilldetail Set',
'									  TNO=:TNO,',
'					SNO=:SNO,',
'					SERIALNO=:SERIALNO,',
'					PURCHASEORDERTNO=:PURCHASEORDERTNO,',
'					ITEMCODE=:ITEMCODE,',
'					ITEMSPECIFICATIONCODE=:ITEMSPECIFICATIONCODE,',
'					DESCRIPTION=:DESCRIPTION,',
'					QUANTITY1=:QUANTITY1,',
'					QUANTITY2=:QUANTITY2,',
'					RATEMEASURINGUNITCODE=:RATEMEASURINGUNITCODE,',
'					RATE=:RATE,',
'					AMOUNT=:AMOUNT,',
'					FOOTERAMOUNT=:FOOTERAMOUNT,',
'					TOTALAMOUNT=:TOTALAMOUNT,',
'					DOCUMENTSTATUSCODE=:DOCUMENTSTATUSCODE,',
'					REMARK=:REMARK,',
'					OURRG23DNO=:OURRG23DNO,',
'					PARTYRG23DNO=:PARTYRG23DNO,',
'					ROUNDING=:ROUNDING,',
'					FOOTERAMOUNTWITHRATE=:FOOTERAMOUNTWITHRATE,',
'					JOBORDERTNO=:JOBORDERTNO,',
'					TAXRULECODE=:TAXRULECODE,',
'					PRORATA=:PRORATA,',
'					QUALITYCODE=:QUALITYCODE',
'',
'',
'            WHERE TNO = :P143_TNO',
'              and rowid = :ROWID;',
'',
'        when ''D'' then',
'            Delete From purchasebilldetail',
'            Where TNo = :P143_TNO',
'              and SNO = :SNO',
'              ;',
'    end case;',
'exception when others then',
'    raise_application_error(-20010, sqlerrm);',
'End;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>160357125638322720
);
