,p_triggering_element_type=>'COLUMN'
,p_triggering_region_id=>wwv_flow_imp.id(601383467526650840)
,p_triggering_element=>'QUANTITY1'
,p_condition_element_type=>'COLUMN'
,p_condition_element=>'QUANTITY1'
