    '                TNO,',
    '                SNO,',
    '                ITEMCODE,',
    '                ITEMSPECIFICATIONCODE,',
    '                DESCRIPTION,',
    '                QUANTITY1,',
    '                QUANTITY2',
    '                ',
    '            )',
    '            values',
    '            (',
    '                 ',
    '                    :P155_TNO,',
    '                    globaltno.nextval,',
    '                    i.itemcode,',
    '                    i.ITEMSPECIFICATIONCODE,',
    '                    i.DESCRIPTION,',
    '                    i.q1,',
    '                    i.QUANTITY2',
    '            );',
    '        end loop;',
    '    end if;',
    'end;')),
  'show_processing', 'N')).to_clob
,p_wait_for_result=>'Y'
,p_server_condition_type=>'VAL_OF_ITEM_IN_COND_EQ_COND2'
