 p_id=>wwv_flow_imp.id(603659241000893062)
,p_process_sequence=>50
,p_process_point=>'AFTER_SUBMIT'
,p_region_id=>wwv_flow_imp.id(603657886664893049)
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Detail - Save Interactive Grid Data'
,p_static_id=>'detail-save-interactive-grid-data'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'Begin',
'    case :APEX$ROW_STATUS',
'        when ''C'' then',
'            if :quantity1 = 0 or :quantity1 is null   then',
'                raise_application_error(-20000 , ''Quantity cannot be 0.'');',
'            end if;',
'            Insert Into LOADINGADVICEDETAIL (                 ',
'                                        TNO,',
'                    SNO,',
'                    ITEMCODE,',
'                    ITEMSPECIFICATIONCODE,',
'                    DESCRIPTION,',
'                    QUANTITY1,',
'                    QUANTITY2,',
'                    REMARK',
'            )',
'            Values (',
'               :TNO,',
'                :SNO,',
'                :ITEMCODE,',
'                :ITEMSPECIFICATIONCODE,',
'                :DESCRIPTION,',
'                :QUANTITY1,',
'                :QUANTITY2,',
'                :REMARK ',
'',
'            );',
'        ',
'        when ''U'' then',
'',
'         if :quantity1 = 0 or :quantity1 is null then',
'                raise_application_error(-20000 , ''Quantity cannot be 0.'');',
'            end if;',
'            ',
'            update LOADINGADVICEDETAIL Set',
'                 TNO=:TNO,',
'                SNO=:SNO,',
'                ITEMCODE=:ITEMCODE,',
'                ITEMSPECIFICATIONCODE=:ITEMSPECIFICATIONCODE,',
'                DESCRIPTION=:DESCRIPTION,',
'                QUANTITY1=:QUANTITY1,',
'                QUANTITY2=:QUANTITY2,',
'                REMARK=:REMARK          ',
'            WHERE TNO = :P155_TNO',
'              and rowid = :ROWID;',
'',
'        when ''D'' then',
'            Delete From LOADINGADVICEDETAIL',
'            Where TNo = :P155_TNO',
'              and SNO = :SNO',
'              ;',
'    end case;',
'exception when others then',
'    raise_application_error(-20010, sqlerrm);',
'End;',
'',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>163272895749966538
);
