'                    tModuleCode,',
'                    :global_CompanyCode,',
'                    :global_FinancialYearCode,',
'                    :P155_LocationCode,',
'                    :P155_DocTypeCode,',
'                    NULL,',
'                    TO_DATE(:P155_LOADINGADVICEDATE, ''DD-MM-RRRR'')',
'                    );',
'    end if;',
'    ',
'end;'))
,p_process_clob_language=>'PLSQL'
