  'language', 'PLSQL',
  'plsql_code', wwv_flow_string.join(wwv_flow_t_varchar2(
    'begin',
    '		for vTAC ',
    '				in (',
    '						select',
    '								b.SNo,',
    '								c.TermsAndConditionHeadName,',
    '								c.TermsAndConditionHeadCode,',
    '								b.TermsAndConditionValue',
